#!/usr/bin/env node
/** Inspect actual build output, including links generated by MDX/Astro components. */
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { dirname, extname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse } from 'parse5';
import { SITE_BASE } from './lib/docs-model.mjs';
import { readArticleModules } from './lib/article-structure.mjs';

const ORIGIN = 'https://vichxuan.github.io';
function walk(dir, files = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) walk(path, files);
    else if (entry.isFile() && entry.name.endsWith('.html')) files.push(path);
  }
  return files;
}

function pageInfo(file) {
  const ids = new Set();
  const references = [];
  const moduleHeadings = [];
  const mathErrors = [];
  const textOf = (node) => node.value ?? (node.childNodes ?? []).map(textOf).join('');
  const visit = (node, inArticle = false) => {
    const attrs = Object.fromEntries((node.attrs ?? []).map((a) => [a.name, a.value]));
    const classes = (attrs.class ?? '').split(/\s+/);
    const article = inArticle || classes.includes('sl-markdown-content');
    if (article && node.tagName === 'h2') moduleHeadings.push(textOf(node).replace(/\s+/g, ' ').trim());
    if (classes.includes('katex-error')) mathErrors.push(attrs.title || textOf(node));
    if (attrs.id) ids.add(attrs.id);
    if (node.tagName === 'a' && attrs.name) ids.add(attrs.name);
    for (const name of ['href', 'src']) {
      if (attrs[name]) references.push({ value: attrs[name], attribute: name, tag: node.tagName });
    }
    for (const child of node.childNodes ?? []) visit(child, article);
    if (node.content) visit(node.content, article);
  };
  visit(parse(readFileSync(file, 'utf8')));
  return { ids, references, moduleHeadings, mathErrors };
}

export function validateSite(dist, entries = []) {
  if (!existsSync(dist)) return { pages: 0, references: 0, errors: [`build output missing: ${dist}`] };
  const files = walk(dist);
  const parsed = new Map(files.map((file) => [file, pageInfo(file)]));
  const errors = [];
  let references = 0;
  for (const entry of entries.filter((e) => e.status === 'draft')) {
    if (existsSync(join(dist, entry.slug, 'index.html')) || existsSync(join(dist, `${entry.slug}.html`))) errors.push(`draft emitted in production: ${entry.slug}`);
  }
  const published = entries.filter((e) => e.status === 'published');
  const modules = published.length ? readArticleModules() : [];
  for (const entry of published) {
    const file = [join(dist, entry.slug, 'index.html'), join(dist, `${entry.slug}.html`)].find((path) => parsed.has(path));
    if (!file) { errors.push(`published article missing from build: ${entry.slug}`); continue; }
    const actual = parsed.get(file).moduleHeadings;
    if (actual.length !== modules.length || modules.some((heading, i) => actual[i] !== heading)) {
      errors.push(`${entry.slug}: rendered H2 module sequence mismatch (expected ${modules.length} standard modules in order; found ${actual.length}): ${actual.join(' / ')}`);
    }
  }
  for (const [file, info] of parsed) {
    const fileRel = relative(dist, file).split('\\').join('/');
    for (const error of info.mathErrors) errors.push(`${fileRel}: KaTeX error: ${error}`);
    const route = fileRel === 'index.html' ? '' : fileRel.endsWith('/index.html') ? fileRel.slice(0, -10) : fileRel;
    const from = new URL(`${SITE_BASE}/${route}`, ORIGIN);
    for (const reference of info.references) {
      const raw = reference.value;
      if (/^(?:data:|blob:|mailto:|tel:|javascript:)/i.test(raw)) continue;
      let url;
      try { url = new URL(raw, from); } catch { errors.push(`${fileRel}: invalid ${reference.attribute}: ${raw}`); continue; }
      if (url.origin !== ORIGIN || !['http:', 'https:'].includes(url.protocol)) continue;
      // Absolute URLs to the author's separate homepage are outside this project.
      if (!url.pathname.startsWith(`${SITE_BASE}/`) && url.pathname !== SITE_BASE) {
        if (/^(?:https?:)?\/\//i.test(raw)) continue;
        errors.push(`${fileRel}: local ${reference.attribute} escapes site base: ${raw}`);
        continue;
      }
      references++;
      let local;
      try { local = decodeURIComponent(url.pathname.slice(SITE_BASE.length)); } catch { errors.push(`${fileRel}: invalid URL encoding: ${raw}`); continue; }
      let target = resolve(dist, '.' + local);
      if (target !== resolve(dist) && !target.startsWith(resolve(dist) + '/')) { errors.push(`${fileRel}: path escapes build output: ${raw}`); continue; }
      if (existsSync(target) && statSync(target).isDirectory()) target = join(target, 'index.html');
      if (!existsSync(target) && !extname(target) && existsSync(`${target}.html`)) target += '.html';
      if (!existsSync(target) || !statSync(target).isFile()) { errors.push(`${fileRel}: broken ${reference.attribute}: ${raw}`); continue; }
      if (url.hash && /\.(?:html|svg)$/.test(target)) {
        let id;
        try { id = decodeURIComponent(url.hash.slice(1)); } catch { errors.push(`${fileRel}: invalid fragment encoding: ${raw}`); continue; }
        // Text fragments are browser search instructions, not element IDs.
        id = id.split(':~:text=')[0];
        if (!id) continue;
        if (!parsed.has(target)) parsed.set(target, pageInfo(target));
        if (!parsed.get(target).ids.has(id)) errors.push(`${fileRel}: missing fragment #${id}: ${raw}`);
      }
    }
  }
  return { pages: files.length, references, errors };
}

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const dist = resolve(ROOT, process.argv[2] ?? 'dist');
  const map = JSON.parse(readFileSync(join(ROOT, 'src/data/content-map.json'), 'utf8'));
  const result = validateSite(dist, map.entries);
  for (const error of result.errors) console.error(`  ✗ ${error}`);
  if (result.errors.length) {
    console.error(`site validation FAILED (${result.errors.length} errors)`);
    process.exitCode = 1;
  } else console.log(`site validation OK: ${result.pages} HTML pages, ${result.references} local href/src references and fragments`);
}
